/**
 * Builds or updates a data table for screen readers, hidden from view, for
 * `owner` (a chart, or a series not in a chart): a row for each category or
 * date, a column for each series. No columns take it away. Returns the table.
 *
 * @ignore
 */
export function renderDataTable(owner: Sprite, table: HTMLTableElement | undefined, columns: Array<IDataTableColumn>): HTMLTableElement | undefined {
	const container = owner._root._getReaderContainer();
	if (!container || !columns.length || owner.isDisposed()) {
		if (table && table.parentNode) {
			table.parentNode.removeChild(table);
		}
		return;
	}

	// Rows in the order the categories or dates first come
	const labels: Array<string> = [];
	const rows: { [label: string]: Array<string> } = {};
	$array.each(columns, (column, index) => {
		$array.each(column.items, (item) => {
			let row = rows[item.label];
			if (!row) {
				row = [];
				rows[item.label] = row;
				labels.push(item.label);
			}
			row[index] = item.text;
		});
	});

	if (!table) {
		table = document.createElement("table");
		table.className = "am5-data-table";
	}
	if (table.parentNode !== container) {
		container.appendChild(table);
	}

	// Built again only if anything in it changed (zooming marks values dirty)
	const ariaLabel = owner.get("ariaLabel");
	const key = JSON.stringify([ariaLabel, $array.map(columns, (column) => column.name), labels, $array.map(labels, (label) => rows[label])]);
	if ((<any>table)._am5Key === key) {
		return table;
	}
	(<any>table)._am5Key = key;

	while (table.firstChild) {
		table.removeChild(table.firstChild);
	}

	if (ariaLabel) {
		const caption = document.createElement("caption");
		caption.textContent = populateString(owner, ariaLabel);
		table.appendChild(caption);
	}

	const cell = (tag: string, text: string, scope?: string) => {
		const element = document.createElement(tag);
		element.textContent = text;
		if (scope) {
			element.setAttribute("scope", scope);
		}
		return element;
	};

	const head = document.createElement("thead");
	const headRow = document.createElement("tr");
	headRow.appendChild(cell("th", owner._root.language.translate("Category"), "col"));
	$array.each(columns, (column) => {
		headRow.appendChild(cell("th", column.name, "col"));
	});
	head.appendChild(headRow);
	table.appendChild(head);

	const body = document.createElement("tbody");
	$array.each(labels, (label) => {
		const tr = document.createElement("tr");
		tr.appendChild(cell("th", label, "row"));
		const row = rows[label];
		$array.each(columns, (_column, index) => {
			tr.appendChild(cell("td", row[index] || ""));
		});
		body.appendChild(tr);
	});
	table.appendChild(body);

	return table;
}

export interface ISeriesSettings extends IComponentSettings {

	/**
	 * Name of the series.
	 */
	name?: string;

	/**
	 * Describes the series' data to screen readers in a few short sentences:
	 * how many values it has, its highest and lowest, and where the data has
	 * an order (XY series), its first and last.
	 *
	 * The summary goes to the series' legend item, and to the series itself
	 * when it is not in a chart (a hierarchy, flow or word cloud), for which
	 * the series has to be `focusable`. In a chart, set `ariaSummary` on the
	 * chart instead: then `false` here leaves this series out.
	 *
	 * @since 5.24.0
	 * @see {@link https://docs.amcharts.com/v5/concepts/accessibility/#data-summary} for more info
	 */
	ariaSummary?: boolean;

	/**
	 * Gives screen readers the series' data as a table, hidden from view: a
	 * row for each category or date, with its value. Screen readers can move
	 * through it by row and column.
	 *
	 * With grouped data (a date axis with `groupData`), the table has the
	 * groups shown when the chart is zoomed out all the way, whatever the zoom.
	 *
	 * In a chart, set `ariaDataTable` on the chart instead, for one table with
	 * a column for each series: then `false` here leaves this series out.
	 * A series not in a chart (a hierarchy, flow or word cloud) with `true`
	 * gets a table of its own.
	 *
	 * @since 5.24.0
	 * @see {@link https://docs.amcharts.com/v5/concepts/accessibility/#data-table} for more info
	 */
	ariaDataTable?: boolean;

	/**
	 * A key to look up in data for an id of the data item.
	 */
	idField?: string;

	/**
	 * A key to look up in data for a URL to open when the data item's element
	 * (a bullet, column, slice, map polygon or map line) is clicked. Links are
	 * off until this is set.
	 *
	 * @since 5.20.7
	 */
	urlField?: string;

	/**
	 * Where a data item's URL opens: `"_self"` for the same window, `"_blank"`
	 * for a new tab, or a named window / frame. A chart embedded in an iframe
	 * usually wants `"_blank"` or `"_top"`.
	 *
	 * @default "_self"
	 * @since 5.20.7
	 */
	linkTarget?: string;

	/**
	 * A key to look up in data for a numeric value of the data item. Some
	 * series draw their elements by it; heat rules can use it too.
	 */
	valueField?: string;

	/**
	 * A key to look up in data for an extra numeric value of the data item
	 * (`customValue`), e.g. for heat rules.
	 */
	customValueField?: string;

	/**
	 * Text template for the item's label in a [[Legend]].
	 */
	legendLabelText?: string;

	/**
	 * Text template for the item's value label in a [[Legend]].
	 */
	legendValueText?: string;

	/**
	 * Shows and hides the data items one after another instead of all at
	 * once, including in the initial animation. Works in XY and percent
	 * series.
	 *
	 * @see {@link https://docs.amcharts.com/v5/concepts/animations/#animation-of-series} for more info
	 */
	sequencedInterpolation?:boolean;

	/**
	 * Extra delay in milliseconds between the animations of consecutive data
	 * items, with `sequencedInterpolation`.
	 *
	 * @see {@link https://docs.amcharts.com/v5/concepts/animations/#animation-of-series} for more info
	 */
	sequencedDelay?:number;

	/**
	 * Heat rules to apply to the series' elements. A rule without `minValue`
	 * and `maxValue` needs `calculateAggregates` to find the value range.
	 *
	 * @see {@link https://docs.amcharts.com/v5/concepts/settings/heat-rules/} for more info
	 */
	heatRules?:IHeatRule[];

	/**
	 * Makes the series compute aggregate values, such as sums, averages, lows,
	 * highs and changes.
	 *
	 * Enable it only if they are used, e.g. in tooltips, data fields or heat
	 * rules.
	 */
	calculateAggregates?: boolean;

	/**
	 * Series stroke color.
	 *
	 * @see {@link https://docs.amcharts.com/v5/charts/xy-chart/series/#series-colors} for more info
	 */
	stroke?: Color;

	/**
	 * Series fill color.
	 *
	 * @see {@link https://docs.amcharts.com/v5/charts/xy-chart/series/#series-colors} for more info
	 */
	fill?: Color;

	/**
	 * Series fill pattern.
	 *
	 * @see {@link https://docs.amcharts.com/v5/concepts/colors-gradients-and-patterns/patterns/} for more info
	 * @since 5.10.0
	 */
	fillPattern?: Pattern;

	/**
	 * Series fill gradient.
	 *
	 * @see {@link https://docs.amcharts.com/v5/concepts/colors-gradients-and-patterns/gradients/} for more info
	 */
	fillGradient?: Gradient;

	/**
	 * Series stroke gradient.
	 *
	 * @see {@link https://docs.amcharts.com/v5/concepts/colors-gradients-and-patterns/gradients/} for more info
	 */
	strokeGradient?: Gradient;

	/**
	 * The series' data item in a [[Legend]].
	 *
	 * @readonly
	 */
	legendDataItem?: DataItem<ILegendDataItem>;

	/**
	 * Fields to leave out of `calculateAggregates`, to save work where their
	 * aggregates are not needed.
	 *
	 * @since 5.14.4
	 */
	excludeFromAggregate?: Array<string>;

	/**
	 * Hides a label in the series' bullets where it would overlap a label
	 * shown before it, or be cut off at the edge of the area it is drawn in.
	 * Labels of the chart's earlier series come first, then those of earlier
	 * data items. A hidden label comes back once it fits.
	 *
	 * Only labels are hidden: a bullet's circle or other shape stays. A label
	 * with its own `forceHidden`, or in a bullet with `stacked` set, is left
	 * as it is. Labels of series without this setting are never hidden, and
	 * the others make room for them.
	 *
	 * @default false
	 * @since 5.22.0
	 * @see {@link https://docs.amcharts.com/v5/concepts/common-elements/bullets/#hiding-overlapping-labels} for more info
	 */
	autoLabels?: boolean;
}

